import Foundation

/// A weather-like effect the stage can wear for one exchange. The visual is drawn by
/// `StageFXLayer`; the sound is generated by `StageSounds`; neither is bundled art.
enum StageEffect: String, CaseIterable, Identifiable {
    case rain, storm, snow, fog, embers, sparkle, wind

    var id: String { rawValue }

    var label: String {
        switch self {
        case .rain: "Rain"
        case .storm: "Storm"
        case .snow: "Snow"
        case .fog: "Fog"
        case .embers: "Embers"
        case .sparkle: "Sparkle"
        case .wind: "Wind"
        }
    }

    var symbol: String {
        switch self {
        case .rain: "cloud.rain.fill"
        case .storm: "cloud.bolt.rain.fill"
        case .snow: "snowflake"
        case .fog: "cloud.fog.fill"
        case .embers: "flame.fill"
        case .sparkle: "sparkles"
        case .wind: "wind"
        }
    }

    /// How long an effect lives before it fades on its own.
    static let lifetime: TimeInterval = 30
}

/// One thing a character can actually do, with the words the visitor can use to ask for it.
struct StageAbility {
    let effect: StageEffect
    /// In the character's voice: "call a storm", "wake the fireflies".
    let name: String
    /// A line the visitor can say verbatim.
    let example: String
}

extension StageEffect {
    /// Each character has a short, fixed set. The first is their signature, used when they are
    /// asked to show off. Keeping the sets here lets the brain, the rail and the reply brief
    /// agree on what a character can do.
    private static let abilities: [String: [StageAbility]] = [
        "silas": [
            .init(effect: .storm, name: "call a storm", example: "Show me a storm."),
            .init(effect: .wind, name: "raise a gale", example: "Raise a gale."),
            .init(effect: .rain, name: "bring the rain", example: "Bring the rain."),
        ],
        "morwenna": [
            .init(effect: .fog, name: "summon the deep fog", example: "Summon the fog."),
            .init(effect: .rain, name: "call the tide's rain", example: "Call the rain."),
            .init(effect: .sparkle, name: "wake the drowned lights", example: "Wake the drowned lights."),
        ],
        "mortlake": [
            .init(effect: .fog, name: "raise the churchyard mist", example: "Raise the mist."),
            .init(effect: .wind, name: "stir the leaves", example: "Stir the leaves."),
            .init(effect: .sparkle, name: "light the lanterns", example: "Light the lanterns."),
        ],
        "azgorath": [
            .init(effect: .embers, name: "set the hall alight", example: "Set the hall alight."),
            .init(effect: .storm, name: "crack the sky", example: "Crack the sky."),
            .init(effect: .fog, name: "call the brimstone haze", example: "Call the haze."),
        ],
        "fennick": [
            .init(effect: .sparkle, name: "wake the fireflies", example: "Wake the fireflies."),
            .init(effect: .wind, name: "call the forest wind", example: "Call the wind."),
            .init(effect: .rain, name: "ask the leaves for rain", example: "Ask the leaves for rain."),
        ],
        "thing": [
            .init(effect: .fog, name: "thicken the dark", example: "Thicken the dark."),
            .init(effect: .wind, name: "make the house breathe", example: "Make the house breathe."),
        ],
        "vyrmathrax": [
            .init(effect: .embers, name: "breathe embers", example: "Breathe embers."),
            .init(effect: .storm, name: "darken the sky", example: "Darken the sky."),
            .init(effect: .wind, name: "beat my wings", example: "Beat your wings."),
        ],
        "grub": [
            .init(effect: .sparkle, name: "make the mushrooms glow", example: "Make the mushrooms glow."),
            .init(effect: .embers, name: "light the campfire", example: "Light the campfire."),
        ],
        "aldric": [
            .init(effect: .sparkle, name: "cast a working", example: "Cast a working."),
            .init(effect: .storm, name: "call lightning", example: "Call lightning."),
            .init(effect: .fog, name: "summon a veil", example: "Summon a veil."),
        ],
        "snowqueen": [
            .init(effect: .snow, name: "bring the snow", example: "Bring the snow."),
            .init(effect: .wind, name: "raise the blizzard", example: "Raise the blizzard."),
            .init(effect: .fog, name: "freeze the air", example: "Freeze the air."),
        ],
        "bramwell": [
            .init(effect: .wind, name: "snap the banner", example: "Snap the banner."),
            .init(effect: .sparkle, name: "make the steel shine", example: "Make the steel shine."),
            .init(effect: .storm, name: "call a squall", example: "Call a squall."),
        ],
        "godmother": [
            .init(effect: .sparkle, name: "grant a little magic", example: "Grant a little magic."),
            .init(effect: .wind, name: "stir the air", example: "Stir the air."),
            .init(effect: .snow, name: "let it snow", example: "Let it snow."),
        ],
    ]

    static func abilities(for id: String) -> [StageAbility] {
        abilities[id] ?? []
    }

    static func signature(for id: String) -> StageEffect {
        abilities(for: id).first?.effect ?? .sparkle
    }

    /// Asked in plain words, so this is matched rather than inferred. It only decides whether
    /// to brief the reply; the brain still decides which effect to show.
    static func asksForCapabilities(_ text: String) -> Bool {
        let lower = text.lowercased()
        return capabilityPhrases.contains { lower.contains($0) }
    }

    private static let capabilityPhrases = [
        "what can you do",
        "what are you capable of",
        "what are your capabilities",
        "what are your abilities",
        "what can you actually do",
        "what are your powers",
        "what powers do you have",
        "show me what you can do",
        "show me what you're capable of",
        "show me what you are capable of",
        "what else can you do",
        "tell me what you can do",
        "what are you able to do",
        "how can you help",
        "what do you do",
    ]
}

#if DEBUG
extension StageEffect {
    static func selfCheck() {
        for persona in Persona.all {
            let list = abilities(for: persona.id)
            assert((2...3).contains(list.count), "\(persona.id) needs two or three abilities")
            assert(Set(list.map(\.effect)).count == list.count, "\(persona.id) repeats an ability")
            assert(list.allSatisfy { !$0.name.isEmpty && !$0.example.isEmpty }, "\(persona.id) has an empty ability")
        }
        assert(asksForCapabilities("So what can you do?"), "capability phrase missed")
        assert(!asksForCapabilities("Tell me a story."), "plain line read as a capability question")
    }
}
#endif
